mapper.select:
SELECT
FROM book b LEFT JOIN book_category c ON b.category_id = c.id LEFT JOIN book_reading_progress p ON p.book_id = b.id AND p.user_uuid = #{userUuid} LEFT JOIN book_chapter pc ON pc.id = p.chapter_id AND pc.status = 1
ORDER BY b.update_time DESC, b.id DESC LIMIT #{offset}, #{limit}

SELECT user_uuid, book_id, chapter_id, scroll_percent
FROM book_reading_progress
WHERE user_uuid = #{userUuid} AND book_id = #{bookId}

mapper.update:
UPDATE book_reading_progress
SET chapter_id = #{chapterId}, scroll_percent = 0
WHERE user_uuid = #{userUuid} AND book_id = #{bookId}

UPDATE book_reading_progress
SET chapter_id = #{chapterId}, scroll_percent = #{scrollPercent}
WHERE user_uuid = #{userUuid} AND book_id = #{bookId}
